class Solution:
    def closestToTarget(self, arr: List[int], target: int) -> int:
        count = BitCount(max(arr).bit_length())
        result, left = float("inf"), 0
        for right in range(len(arr)):
            count += arr[right]
            while left <= right:
                f = count.bit_and()
                result = min(result, abs(f-target))
                if f >= target:
                    break
                count -= arr[left]
                left += 1
        return result

