class Solution:
    def numSplits(self, s: str) -> int:
        one = set()
        two = set()
        dic = {}

        for i in s:
            dic[i] = dic.get(i, 0) + 1
            two.add(i)
        tot = 0

        for i in s:
            one.add(i)
            dic[i] -= 1
            if dic[i] == 0:
                two.remove(i)

            if len(one) == len(two):
                tot += 1
        return tot

import collections

class Solution:
    def numSplits(self, s: str) -> int:
        left_count, right_count = collections.Counter(), collections.Counter(s)
        result = 0
        for c in s:
            left_count[c] += 1
            right_count[c] -= 1
            if not right_count[c]:
                del right_count[c]
            if len(left_count) == len(right_count):
                result += 1
        return result

